<?php require_once __DIR__.'/app/core/bootstrap.php'; $title='Search Arusha'; $q=trim($_GET['q']??''); $like='%'.$q.'%'; $st=db()->prepare("SELECT t.*,d.name destination FROM tours t LEFT JOIN destinations d ON d.id=t.destination_id WHERE t.status='active' AND (t.title LIKE ? OR t.short_description LIKE ? OR d.name LIKE ?) ORDER BY t.featured DESC,t.id DESC"); $st->bind_param('sss',$like,$like,$like);$st->execute();$results=$st->get_result()->fetch_all(MYSQLI_ASSOC); require __DIR__.'/app/views/header.php'; ?>
<section class="search-page"><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Search</div><h2>Results<?=($q?' for “'.e($q).'”':'')?></h2></div></div><?php if(!$results): ?><div class="empty">No active tour matched your search yet. Try “safari”, “Meru”, or leave search blank to browse the collection.</div><?php else: ?><div class="grid"><?php foreach($results as $t): ?><article class="card"><div class="card-img"><img src="<?=e(media_url($t['image']))?>" alt=""></div><div class="card-body"><div class="meta"><span><?=e($t['destination']??'Arusha')?></span><span><?=$t['duration_days']?> days</span></div><h3><?=e($t['title'])?></h3><p class="muted"><?=e($t['short_description'])?></p><div class="row-between"><span class="price">From <?=money((float)$t['base_price'])?></span><a class="btn btn-dark" href="<?=url('tour.php?id='.$t['id'])?>">View</a></div></div></article><?php endforeach; ?></div><?php endif; ?></section>
<?php require __DIR__.'/app/views/footer.php'; ?>
